// Verifica la firma HMAC-SHA256 del backend y prepara los payloads de WhatsApp.
const crypto = require('crypto');

const secret = $env.WEBHOOK_SECRET || '';
const incoming = $input.first().json;
const signature = (incoming.headers['x-badboys-signature'] || '').toString();
const raw = JSON.stringify(incoming.body);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');

if (!signature || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) {
  throw new Error('Firma HMAC inválida: el webhook no proviene del backend');
}

const { tenant, appointment: appt } = incoming.body;
const services = appt.services.map((s) => s.name).join(', ');
const totalCop = new Intl.NumberFormat('es-CO').format(appt.total_cop);

// Plantilla pre-aprobada en Meta: confirmacion_turno (ver docs/WHATSAPP_SETUP.md)
const waClientPayload = {
  messaging_product: 'whatsapp',
  to: appt.customer_whatsapp,
  type: 'template',
  template: {
    name: 'confirmacion_turno',
    language: { code: 'es_CO' },
    components: [
      {
        type: 'body',
        parameters: [
          { type: 'text', text: appt.customer_name },
          { type: 'text', text: appt.date_local },
          { type: 'text', text: appt.time_local },
          { type: 'text', text: appt.barber.name },
          { type: 'text', text: services },
          { type: 'text', text: String(appt.daily_number) },
          { type: 'text', text: appt.manage_code },
        ],
      },
      {
        type: 'button',
        sub_type: 'url',
        index: '0',
        parameters: [{ type: 'text', text: appt.manage_code }],
      },
    ],
  },
};

// Alerta interna al negocio: plantilla notificacion_interna ({{1}} = resumen)
const resumen = `Nuevo turno #${appt.daily_number}: ${appt.customer_name} — ${appt.date_local} ${appt.time_local} con ${appt.barber.name}. Servicios: ${services}. Total: $${totalCop}.`;
const waBusinessPayload = {
  messaging_product: 'whatsapp',
  to: tenant.whatsapp_number,
  type: 'template',
  template: {
    name: 'notificacion_interna',
    language: { code: 'es_CO' },
    components: [
      { type: 'body', parameters: [{ type: 'text', text: resumen }] },
    ],
  },
};

return [{ json: { waClientPayload, waBusinessPayload, appointmentId: appt.id } }];
